    // Pure observation/bookkeeping for the +natural=1 run.  Inert while
    // natural_enable is false, so every ordinary scenario is unchanged.
    bool        natural_enable = false;
    std::string natural_first  = "v";
    uint64_t    natural_bytes  = 2048;
    std::string nat_trace_path;
    FILE*       nat_trace      = nullptr;
    // §50 shared-source switch (test-only).  When true the two INDEPENDENT
    // A/V translations resolve their SOURCE leaf to the SAME physical page(s).
    // Only the memory image and the CONF value change; the ordinary path
    // (shared_source == false) is bit-identical to the pre-§50 behaviour.
    bool        shared_source  = false;
    // Runtime destination offset: NAT_DST_OFF (3072) normally, forced to 0 by
    // run_natural() when shared_source is set (single 2 KiB page by default).
    uint32_t    nat_dst_off    = NAT_DST_OFF;

    // A-side source physical base.  Shared mode reuses the V source PA, so the
    // two independent context records (DID10 root 0x20000 / DID11 root 0x30000)
    // resolve to one physical range.  Every A-source read must go through this.
    uint64_t nat_a_src_pa() const {
        return shared_source ? NAT_V_SRC_PA : NAT_A_SRC_PA;
    }"
